        require(_epoches[i] < prevEpoch, "Duplicate or invalid epoch order");
        prevEpoch = _epoches[i];

        uint256 claimableAmount = _claimable(_epoches[i], msg.sender);
        if (claimableAmount > 0) {
            _claim(_epoches[i], _to, claimableAmount);
